// Browser-local, explicit research records. No network or automatic upload.
export const NOTEBOOK_VERSION=1;
export const RELEASE='20261026-electronic1';
export const MAX_PROJECT_BYTES=32*1024*1024;
const ACTIONS=new Set('analyze induce product match_bands magnetictb crystkit symbolic carat crystkit_ext carat_integral integral_normalizer symbolic_interfaces arithmetic_centralizer symbolic_spacegroups structure_bc standard_labels teaching_labs phonons tensors phase diffraction phonopy phonon_modes band_connectivity phonon_thermo distortion_lab magnon_lab qha_lab pairing_lab shg_lab unfold_lab'.split(' '));
const PROGRESS=['pointgroups.progress','academy.progress','academy.derivations','lie.progress','lie.derivations','observables.progress','structure-dynamics.progress','material-research.progress','coupled-materials.progress','electronic-materials.progress'].map(x=>'symmetry-lab.'+x+'.v1');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const object=x=>x&&typeof x==='object'&&!Array.isArray(x);
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
const clone=x=>JSON.parse(JSON.stringify(x));
const bytes=x=>new TextEncoder().encode(typeof x==='string'?x:JSON.stringify(x)).length;
let latest=null,dbPromise,storageWarning='';
const memory=new Map();
export function validateJSON(value,depth=0,counter={n:0}){
 if(depth>60||++counter.n>1500000)throw Error('研究记录的数据层级或项目数过多');
 if(value===null||typeof value==='string'||typeof value==='boolean')return;
 if(typeof value==='number'){if(!Number.isFinite(value))throw Error('研究记录含非有限数值');return;}
 if(typeof value!=='object')throw Error('研究记录须为 JSON 数据');
 for(const [key,item] of Object.entries(value)){if(['__proto__','prototype','constructor'].includes(key))throw Error('研究记录包含不允许的对象键');validateJSON(item,depth+1,counter);}
}
export function safeRecordRoute(route){return typeof route==='string'&&route.length<=1000&&/^(?:compute(?:\/|$)|classroom(?:\/|\?|$)|atlas(?:\/|\?|$)|structure(?:\?|$)|workbench(?:\?|$)|products(?:\?|$)|bands(?:\?|$)|magnetictb(?:\?|$)|crystkit(?:\?|$)|advanced(?:\?|$))[a-zA-Z0-9_/?=&.%+\-]*$/.test(route)?route:'compute';}
export function captureCalculation(action,input,result,context={}){
 latest=null;if(!ACTIONS.has(action))return;
 try{validateJSON(input);validateJSON(result);if(!object(input)||!object(result))throw Error('计算输入和结果须为 JSON 对象');const record={id:uid(),action,input:clone(input),result:clone(result),route:safeRecordRoute(context.route),title:String(context.title||action).slice(0,160),material:String(context.material||'').slice(0,120),created:new Date().toISOString(),release:RELEASE,notes:''};validateJSON(record);if(bytes(record)>MAX_PROJECT_BYTES)throw Error('计算数据超过单项目 32 MiB，请使用计算器的结果导出');latest=record;return record;}catch(error){latest=null;storageWarning=error.message;}
}
export const latestCalculation=()=>latest?clone(latest):null;
function validateProgress(snapshot){validateJSON(snapshot);if(!object(snapshot))throw Error('学习进度快照须为 JSON 对象');for(const [key,value]of Object.entries(snapshot)){if(!PROGRESS.includes(key))throw Error('项目包含未知的学习进度键');if(!object(value)||bytes(value)>200000)throw Error('每组学习进度须为不超过 200 kB 的 JSON 对象');}return snapshot;}
export function progressSnapshot(){const result={};for(const key of PROGRESS){try{const raw=localStorage.getItem(key);if(raw&&bytes(raw)<=200000){const value=JSON.parse(raw);validateProgress({[key]:value});result[key]=value;}}catch{}}return result;}
export function restoreProgress(snapshot){
 validateProgress(snapshot);const updates=Object.entries(snapshot).map(([key,value])=>[key,JSON.stringify(value)]),backup=new Map(updates.map(([key])=>[key,localStorage.getItem(key)])),written=[];
 try{for(const [key,value]of updates){localStorage.setItem(key,value);written.push(key);}}catch(error){let rollbackFailed=false;for(const key of written.reverse()){try{const old=backup.get(key);if(old===null)localStorage.removeItem(key);else localStorage.setItem(key,old);}catch{rollbackFailed=true;}}throw Error(rollbackFailed?'学习进度写入失败，且部分旧值无法恢复；请保留项目备份后检查浏览器存储。':'学习进度写入失败，已恢复原有进度；请检查浏览器存储空间。');}return updates.length;
}
export function makeProject({title='我的材料研究',material='',notes=''}={}){return {format:'symmetry-lab-material-project',version:NOTEBOOK_VERSION,id:uid(),title:String(title).slice(0,160),material:String(material).slice(0,120),notes:String(notes).slice(0,20000),created:new Date().toISOString(),updated:new Date().toISOString(),release:RELEASE,records:[],progress:{}};}
export function validateProject(project){
 validateJSON(project);if(!object(project)||project.format!=='symmetry-lab-material-project'||project.version!==NOTEBOOK_VERSION)throw Error('不是受支持的 Symmetry Lab 材料项目（版本 1）');
 if(typeof project.id!=='string'||!project.id||project.id.length>100||typeof project.title!=='string'||project.title.length>160||typeof project.material!=='string'||project.material.length>120||typeof project.notes!=='string'||project.notes.length>20000)throw Error('项目名称、材料或笔记格式不正确');
 if(!Array.isArray(project.records)||project.records.length>40||!object(project.progress))throw Error('每个材料项目最多保存 40 次计算');
 for(const key of ['created','updated','release'])if(typeof project[key]!=='string'||project[key].length>100)throw Error('项目日期或版本格式不正确');
 const ids=new Set();for(const r of project.records){if(!object(r)||typeof r.id!=='string'||!r.id||r.id.length>100||ids.has(r.id)||!ACTIONS.has(r.action)||!object(r.input)||!object(r.result)||typeof r.title!=='string'||r.title.length>160||typeof r.notes!=='string'||r.notes.length>20000||r.route!==safeRecordRoute(r.route))throw Error('项目内的计算记录不完整或含不支持的工具');for(const key of ['created','release'])if(typeof r[key]!=='string'||r[key].length>100)throw Error('计算记录日期或版本格式不正确');if(r.material!==undefined&&(typeof r.material!=='string'||r.material.length>120))throw Error('计算记录材料标签格式不正确');if(r.draftInput!==undefined&&(typeof r.draftInput!=='string'||bytes(r.draftInput)>MAX_PROJECT_BYTES))throw Error('重算输入草稿须为不超过 32 MiB 的文本');ids.add(r.id);}
 validateProgress(project.progress);
 if(bytes(project)>MAX_PROJECT_BYTES)throw Error('项目超过 32 MiB，请拆成多个项目');return project;
}
export function importProject(text){if(bytes(text)>MAX_PROJECT_BYTES)throw Error('导入文件超过 32 MiB');const p=validateProject(JSON.parse(text));const copy=clone(p);copy.id=uid();copy.title=(copy.title+' · 导入副本').slice(0,160);copy.updated=new Date().toISOString();return copy;}
export function addRecord(project,record){validateProject(project);if(!record)throw Error('请先完成一次计算');validateJSON(record);const p=clone(project);p.records.push({...clone(record),id:uid()});p.updated=new Date().toISOString();p.progress=progressSnapshot();return validateProject(p);}
async function db(){if(!dbPromise)dbPromise=new Promise(resolve=>{if(!globalThis.indexedDB){storageWarning='当前环境不支持持久存储，记录仅留在本次页面；请导出项目备份。';return resolve(null);}try{const req=indexedDB.open('symmetry-lab-material-notebook',1);req.onupgradeneeded=()=>req.result.createObjectStore('projects',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>{storageWarning='本地存储不可用，记录仅留在本次页面；请导出项目备份。';resolve(null);};req.onblocked=()=>{storageWarning='本地数据库被其他页面占用，暂存本次页面，请导出备份。';resolve(null);};}catch{storageWarning='浏览器阻止了本地存储，请导出项目备份。';resolve(null);}});return dbPromise;}
export async function saveProject(project){validateProject(project);const value=clone(project);memory.set(value.id,value);const database=await db();if(!database)return value;try{await new Promise((resolve,reject)=>{const tx=database.transaction('projects','readwrite');tx.objectStore('projects').put(value);tx.oncomplete=resolve;tx.onerror=()=>reject(Error('本地保存失败，可能存储空间不足；请先导出项目。'));tx.onabort=()=>reject(Error('本地保存未完成；请导出项目备份。'));});memory.delete(value.id);}catch(error){storageWarning='保存未完成；最新内容保留在本次页面内存，请导出项目备份后再刷新。';throw error;}return value;}
export async function listProjects(){const database=await db();let values=[];if(database){try{values=await new Promise((resolve,reject)=>{const req=database.transaction('projects').objectStore('projects').getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(Error('无法读取本地材料项目'));});}catch(error){if(!memory.size)throw error;storageWarning='本地数据库读取失败；这里只显示本次页面保留的项目，请先导出备份。';}}const merged=new Map(values.map(value=>[value.id,value]));for(const [id,value]of memory)merged.set(id,value);return clone([...merged.values()]).sort((a,b)=>String(b.updated).localeCompare(String(a.updated)));}
export async function renderMaterialNotebook({container,run,cancelRun,download,toast=()=>{},reload=null}){
 container.innerHTML='<div class="obs-page notebook-page"><p>正在读取本机的材料项目…</p></div>';const root=container.firstElementChild,$=s=>root.querySelector(s),current=()=>root.parentNode===container&&container.isConnected!==false;
 let projects=[];try{projects=await listProjects();}catch(error){storageWarning=error.message+'；原数据库未改动，可导入备份或新建项目后重试。';}let project=projects[0]||null,selected=project?.records.at(-1)?.id,busy=false,operationBusy=false;
 const notice=text=>{if($('#nb-status'))$('#nb-status').textContent=text;};
 const save=async(target=project)=>{target.updated=new Date().toISOString();await saveProject(target);projects=await listProjects();};
 const edit=()=>{if(!project)return;for(const [field,id,limit]of [['title','nb-title',160],['material','nb-material',120],['notes','nb-notes',20000]])if($('#'+id))project[field]=$('#'+id).value.slice(0,limit);const record=project.records.find(r=>r.id===selected);if(record){if($('#nb-record-notes'))record.notes=$('#nb-record-notes').value.slice(0,20000);if($('#nb-rerun-input')){const text=$('#nb-rerun-input').value;if(bytes(text)>MAX_PROJECT_BYTES)throw Error('重算输入草稿超过 32 MiB');if(text===JSON.stringify(record.input,null,2))delete record.draftInput;else record.draftInput=text;}}};
 const lock=()=>{if(!current())return;for(const tag of ['button','input','select','textarea'])root.querySelectorAll(tag).forEach(control=>{if(control.id!=='nb-cancel')control.disabled=operationBusy;});if($('#nb-cancel'))$('#nb-cancel').hidden=!busy;};
 async function perform(fn){if(operationBusy)return;operationBusy=true;try{edit();lock();await fn();}catch(e){if(current()){draw();notice(e.message);}}finally{operationBusy=false;lock();}}
 function draw(){if(!current())return;const recent=latestCalculation(),record=project?.records.find(r=>r.id===selected);root.innerHTML=`<header class="obs-header"><span class="obs-eyebrow">ONE MATERIAL · REPRODUCIBLE STEPS</span><h2>材料研究记录</h2><p>把结构、坐标约定、原始输入、计算结果和你的解释放在同一个项目里。点击保存才写入此浏览器，文件不会上传。</p></header><div class="obs-links"><button id="nb-new" class="primary">＋ 新建材料项目</button><label class="secondary">导入项目副本<input id="nb-import" type="file" accept=".json"></label></div><p id="nb-status" role="status">${esc(storageWarning||'本地保存与 JSON 备份相互独立；清除网站数据会移除浏览器内的项目。')}</p>${projects.length?`<label>选择材料项目<select id="nb-project">${projects.map(p=>`<option value="${esc(p.id)}" ${project?.id===p.id?'selected':''}>${esc(p.title)} · ${p.records.length} 次计算</option>`).join('')}</select></label>`:''}${recent?`<aside class="obs-example"><h3>最近一次完成的计算：${esc(recent.title)}</h3><p>${esc(recent.action)} · ${esc(recent.created)} · ${esc(recent.release)}</p><button id="nb-add" class="secondary">将这次计算加入当前项目</button></aside>`:'<p class="obs-model-note">先在计算中心完成一次计算，再点击“记录最近计算”。也可以导入已有项目继续研究。</p>'}${project?`<div class="nb-metadata"><label>项目名称<input id="nb-title" maxlength="160" value="${esc(project.title)}"></label><label>材料与相（用户标记）<input id="nb-material" maxlength="120" value="${esc(project.material)}"></label><label>研究问题与结论<textarea id="nb-notes" rows="4" maxlength="20000">${esc(project.notes)}</textarea></label></div><div class="obs-links"><button id="nb-save" class="primary">保存项目与学习进度</button><button id="nb-export" class="secondary">↓ 导出完整项目 JSON</button><button id="nb-progress" class="secondary">恢复此项目的练习进度</button></div><h3>计算记录 · ${project.records.length} / 40</h3><div class="nb-records">${project.records.map((r,i)=>`<button class="${r.id===selected?'primary':'secondary'}" data-nb-record="${esc(r.id)}">${i+1}. ${esc(r.title)}<small>${esc(r.action)} · ${esc(r.release)}</small></button>`).join('')}</div>${record?`<article class="obs-lesson"><h3>${esc(record.title)}</h3><p>原始计算：${esc(record.created)} · ${esc(record.release)}。保存的数据包含工具返回的单位、模型和坐标约定；当前软件版本为 ${RELEASE}。</p><label>本次计算的解释<textarea id="nb-record-notes" rows="3" maxlength="20000">${esc(record.notes)}</textarea></label><details><summary>原始输入与参数（可复制；下方可创建修改后的重算记录）</summary><pre>${esc(JSON.stringify(record.input,null,2))}</pre></details><details><summary>编辑本次重算输入 JSON</summary><textarea id="nb-rerun-input" rows="10" spellcheck="false">${esc(record.draftInput??JSON.stringify(record.input,null,2))}</textarea></details><div class="obs-links"><button id="nb-rerun" class="secondary" ${busy?'disabled':''}>用当前版本重算为新记录</button><button id="nb-cancel" class="secondary" ${busy?'':'hidden'}>取消重算</button><button id="nb-save-record" class="secondary">保存解释</button><a href="#${esc(record.route)}">打开原工具 →</a></div><details><summary>完整结果</summary><pre>${esc(JSON.stringify(record.result,null,2))}</pre></details></article>`:'<p>当前项目尚无计算记录。项目笔记和学习进度仍可保存。</p>'}`:''}<p class="obs-small">项目最多 32 MiB / 40 次计算。导入创建副本；重算创建新记录，原结果保留。项目数据与导入的材料内容不会自动发布到 GitHub。</p>`;
 $('#nb-new').onclick=()=>perform(async()=>{if(project)await save();project=makeProject();selected=null;await save();draw();});
 $('#nb-import').onchange=e=>perform(async()=>{const file=e.target.files?.[0];if(!file)return;if(file.size>MAX_PROJECT_BYTES)throw Error('导入文件超过 32 MiB');if(project)await save();const p=importProject(await file.text());await saveProject(p);projects=await listProjects();project=p;selected=p.records.at(-1)?.id;draw();notice('已导入为独立副本，原项目及其草稿已保存。');});
 if($('#nb-project'))$('#nb-project').onchange=e=>{const id=e.target.value;return perform(async()=>{if(project)await save();project=projects.find(p=>p.id===id);selected=project?.records.at(-1)?.id;draw();});};
 if($('#nb-add'))$('#nb-add').onclick=()=>perform(async()=>{if(!project)project=makeProject({material:recent.material});project=addRecord(project,recent);selected=project.records.at(-1).id;await save();draw();notice('已保存原始输入、结果、软件版本与当前练习进度。'+storageWarning);});
 if(!project)return;
 $('#nb-save').onclick=()=>perform(async()=>{project.progress=progressSnapshot();await save();notice('项目已保存。'+storageWarning);});
 $('#nb-export').onclick=()=>perform(async()=>{project.progress=progressSnapshot();project.updated=new Date().toISOString();validateProject(project);download(JSON.stringify(project,null,2),'symmetry-material-project.json');notice('已导出完整项目；本次导出不依赖浏览器数据库，可导入恢复。');});
 $('#nb-progress').onclick=()=>perform(async()=>{await save();const count=restoreProgress(project.progress);if(!count){notice('此项目没有已保存的练习进度；当前进度未改动。');return;}notice('已恢复 '+count+' 组练习进度，正在刷新课堂缓存。');if(reload)await reload();else if(await db()&&!memory.size)globalThis.location?.reload?.();else notice('已恢复 '+count+' 组练习进度。当前项目仅在页面内存中，请先导出全部项目，再刷新页面应用课堂进度。');});
 root.querySelectorAll('[data-nb-record]').forEach(b=>b.onclick=()=>perform(async()=>{await save();selected=b.dataset.nbRecord;draw();}));
 if(!record)return;
 $('#nb-save-record').onclick=()=>perform(async()=>{await save();notice('计算解释与重算输入草稿已保存。'+storageWarning);});
 $('#nb-cancel').onclick=()=>cancelRun?.();
 $('#nb-rerun').onclick=()=>perform(async()=>{const input=JSON.parse(record.draftInput??JSON.stringify(record.input));validateJSON(input);if(!object(input))throw Error('重算输入须为 JSON 对象');const targetProject=project,targetId=project.id,sourceRecord=clone(record);await save(targetProject);busy=true;lock();notice('Python 正在重算；当前项目已锁定，将保留原来的记录…');try{const result=await run(sourceRecord.action,input);validateJSON(result);const newRecord={...sourceRecord,id:uid(),input,result,created:new Date().toISOString(),release:RELEASE,title:(sourceRecord.title+' · 重算').slice(0,160),notes:'由记录 '+sourceRecord.id+' 重算；旧结果保留。'};delete newRecord.draftInput;const updated=addRecord(targetProject,newRecord);if(project?.id===targetId){project=updated;selected=updated.records.at(-1).id;}await save(updated);if(current()){draw();notice('重算完成，新旧结果都已保存。'+storageWarning);}}finally{busy=false;lock();}});
 lock();
 }
 draw();
}
